(() => {
  const $ = (id) => document.getElementById(id);
  const key = 'headstart.telemetry.v1';
  let preference = null;
  try { preference = JSON.parse(localStorage.getItem(key)); } catch {}
  const random = () => Array.from(crypto.getRandomValues(new Uint8Array(32)), x => x.toString(16).padStart(2,'0')).join('');
  const text = (tag, value) => { const el=document.createElement(tag);el.textContent=value;return el; };
  async function request(path, body) { const response=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await response.json();if(!response.ok)throw new Error(data.error||'Unavailable');return data; }
  function state() { $('telemetry-consent').checked=preference?.consent===true; }
  state();
  $('telemetry-consent').addEventListener('change',()=>{try{preference={consent:$('telemetry-consent').checked,deletionToken:preference?.deletionToken||random()};localStorage.setItem(key,JSON.stringify(preference));$('privacy-status').textContent=preference.consent?'Optional counts enabled for this browser.':'Optional counts are off. Your local collection is unchanged.';}catch{$('telemetry-consent').checked=false;$('privacy-status').textContent='Browser storage unavailable; counts remain off.';}});
  $('forget-events').addEventListener('click',async()=>{try{if(preference?.deletionToken)await request('/api/events/forget',{deletionToken:preference.deletionToken});localStorage.removeItem(key);preference=null;state();$('privacy-status').textContent='Collected events deleted. Optional counts are off.';}catch{$('privacy-status').textContent='Deletion unavailable. Your deletion key is preserved; retry when the service returns.';}});
  const date = (value) => value ? new Date(value*1000).toLocaleString() : 'Never checked';
  async function health(){ $('health-status').textContent='Loading dated checks…';try{const data=await request('/api/health');$('health-checks').replaceChildren();for(const row of data.checks){const section=text('article','');section.className='ops-check';section.append(text('h3',row.target));const reach=row.reachability;section.append(text('p',`Reachability: ${reach?.category?.replaceAll('_',' ')||'unchecked'}${reach?.stale?' · stale':''} · ${date(reach?.observedAt)}`),text('p',`Interaction: ${row.interactive.status.replaceAll('_',' ')}${row.interactive.stale?' · stale':''} · ${date(row.interactive.observedAt)}`));$('health-checks').append(section);}$('health-status').textContent=data.checks.length?`${data.checks.length} registered demo revisions.`:'No demo checks registered yet. No health result is implied.';if(!data.telemetryAvailable)$('privacy-status').textContent='Server collection is disabled. Your local collection still works.';}catch{$('health-status').textContent='Health service unavailable. Retry to retrieve the last recorded checks.';}}
  $('refresh-health').addEventListener('click',health);health();
  $('load-operations').addEventListener('click',async()=>{try{const data=await request('/api/operations');const list=document.createElement('dl');for(const [name,value]of Object.entries(data.counts)){list.append(text('dt',name.replace(/([A-Z])/g,' $1')),text('dd',String(value)));}list.append(text('dt','Reviewed reference integrations (not user adoption)'),text('dd',data.events.verifiedReuse===null?'Not activated':String(data.events.verifiedReuse)));$('operations-results').replaceChildren(list,text('p',data.indexRecovery));for(const job of data.sourceJobs||[])$('operations-results').append(text('p',`Source scan ${job.id.slice(0,12)}: ${job.status} · attempts ${job.attempts} · next ${date(job.nextCheck)}`));$('operations-status').textContent=data.scheduling;}catch(error){$('operations-status').textContent=error.message;}});
})();
